To systematically analyze the effects of quantization, we begin by isolating the different sources of error. We introduce auxiliary moment estimates, $m'_{t,i}$ and $v'_{t,i}$, which are defined to incorporate the quantization error from the stochastic gradient, $\delta_{t,i}$, but are themselves assumed to be stored with perfect precision. Their dynamics are given by:  egin{equation}  egin{aligned} m'_{t, i} &= eta_1 m'_{t-1, i} + (
abla_i f_t(\wb_{t-1})+\delta_{t,i})\ v'_{t, i} &= eta_2 v'_{t-1, i} + (
abla_i f_t(\wb_{t-1})+\delta_{t,i})^2\ \end{aligned} \end{equation} Throughout the following proof we note $\espt{\cdot}$ the conditional expectation with respect to $f_1, \ldots, f_{t-1}$. In particular, $\wb_{t-1}$, $\vb_{t-1}$ is deterministic knowing $f_1, \ldots, f_{t-1}$. With slightly abuse of notation in the detailed proof, We introduce  egin{equation}\mathcal{G}_t = 
abla F(\wb_{t-1}) \quad 	ext{and} \quad \gb_t = 
abla f_t(\wb_{t-1}).\end{equation} We introduce the update $\ub_t \in \RR^d$, as well as the update without momentum $\Ub_t \in \RR^d$:  egin{equation} u_{t, i} =  rac{m_{t, i}}{\sqrt{\epsilon+v_{t, i}}} \quad 	ext{and}\quad U_{t, i} =  rac{g_{t, i}+\delta_{t,i}}{\sqrt{\epsilon+v'_{t, i}}}. \end{equation} For any $k \in \NN$ with $k < t$, we define $	ilde{v}_{t, k} \in\RR^d$ by  egin{equation} 	ilde{v}_{t, k, i} =  eta_2^{k} v'_{t - k, i} + \esps{t - k}{\sum_{j=t- k + 1}^{t} eta_2^{t-j}(g_{j,i}+\delta_{j,i})^2}, \end{equation} i.e. the contribution from the $k$ last gradients are replaced by their expected value for know values of $f_1, \ldots, f_{t - k - 1}$. Using the smoothness of $F$, we have  egin{align*} &F(\wb_t) \leq F(\wb_{t-1}) - \eta_t \mathcal{G}_t^T \ub_t +  rac{\eta_t^2 L}{2}
orm{\ub_t}^2_2. \end{align*} The overall motivation of our proof is to find a lower bound for $\eta_t \mathcal{G}_t^T \ub_t$.  egin{align} \mathcal{G}_t^T \ub_t=\sum_{i\in[d]}\mathcal{G}_{t, i} rac{m_{t, i}}{\sqrt{\epsilon+v_{t, i}}} \end{align} We can rewrite $\mathcal{G}_t^T \ub_t$ as:  egin{equation} \sum_{i\in[d]}\mathcal{G}_{t, i} rac{m_{t, i}}{\sqrt{\epsilon+v_{t, i}}}=\underbrace{(\sum_{i\in[d]}\mathcal{G}_{t, i} rac{m_{t, i}}{\sqrt{\epsilon+v_{t, i}}}-\sum_{i\in[d]}\mathcal{G}_{t, i} rac{m'_{t, i}}{\sqrt{\epsilon+v'_{t, i}}})}_A+\underbrace{\sum_{i\in[d]}\mathcal{G}_{t, i} rac{m'_{t, i}}{\sqrt{\epsilon+v'_{t, i}}}}_B \end{equation} Here, Term A represents the error component arising from the quantization of the momentum accumulators ($\mathbf{m}_t, \mathbf{v}_t$), while Term B represents the behavior of the update driven by an ideal accumulator. Now we can bound term A. We split A into two parts as before:  egin{equation} |A| \le \underbrace{\left|\sum_{i\in[d]}\mathcal{G}_{t, i} rac{m_{t, i} - m'_{t,i}}{\sqrt{\epsilon+v_{t, i}}}ight|}_{A_1} + \underbrace{\left|\sum_{i\in[d]}\mathcal{G}_{t, i}\left( rac{m'_{t, i}}{\sqrt{\epsilon+v_{t, i}}} -  rac{m'_{t, i}}{\sqrt{\epsilon+v'_{t, i}}}ight)ight|}_{A_2} \end{equation} The first term, $A_1$, which arises from the quantization noise on the first moment $\mb$, is bounded using Lemma~ef{app:lemma:discrete_error_bound} (with $q=q_M$) and Lemma~ef{app:lemma:refined_cauchy}:  egin{align} |A_1| &\le \sum_{i\in[d]}R rac{|m_{t, i}-m'_{t,i}|}{\sqrt{v_{t, i}}} 
onumber \ &\le R\sum_{i\in[d]} rac{\sum_{k=0}^t( eta_1^{t-k}((1+q_M)^{t-k}-1))|
abla_i f_k(\wb_{k-1}) + \delta_{k,i}|}{\sqrt{\sum_{k=0}^t eta_2^{t-k}(1-q_V)^{t-k}(
abla_i f_k(\wb_{k-1}) + \delta_{k,i})^2}} \le q_M \cdot dR \cdot C_q \end{align} where $C_q =  rac{\sqrt{r'(1+r')}}{(1+q_M)(1-r')^{3/2}}$ and $r' =  rac{ eta_1^2(1+q_M)^2}{ eta_2(1-q_V)}$. For the second term, $A_2$, we use the bound on the gradient $
orm{\mathcal{G}_t}_\infty \le R$ and apply Lemma~ef{app:lemma:moment_relation}, which requires a case analysis.  egin{align} 
onumber |A_2| &\le \sum_{i\in[d]}R|m'_{t,i}|\left| rac{1}{\sqrt{\epsilon+v_{t,i}}}- rac{1}{\sqrt{\epsilon+v'_{t,i}}}ight| \ &\le \sum_{i\in[d]}R|m'_{t,i}| \max\left\{  rac{1}{\sqrt{\epsilon+LB_{t,i}}} -  rac{1}{\sqrt{\epsilon+v'_{t,i}}},  rac{1}{\sqrt{\epsilon+v'_{t,i}}} -  rac{1}{\sqrt{\epsilon+UB_{t,i}}} ight\} \end{align} Let $g_{k,i} = 
abla_i f_k(\wb_{k-1}) + \delta_{k,i}$. We analyze the two terms inside the $\max$ for a single coordinate $i$. 	extbf{Case I (Deviation from Lower Bound):} Following the approximation in the provided sketch, we have  egin{align} 
onumber |m'_{t,i}| \left(  rac{1}{\sqrt{\epsilon+LB_{t,i}}} -  rac{1}{\sqrt{\epsilon+v'_{t,i}}} ight) 
onumber &=|m'_{t,i}|\left(  rac{v'_{t,i}-LB_{t,i}}{\sqrt{\epsilon+LB_{t,i}}\sqrt{\epsilon+v'_{t,i}}(\sqrt{\epsilon+LB_{t,i}}+\sqrt{\epsilon+v'_{t,i}})} ight)\ 
onumber &=  rac{|m'_{t,i}|}{\sqrt{\epsilon+LB_{t,i}}}  rac{v'_{t,i} - LB_{t,i}}{\sqrt{\epsilon+v'_{t,i}}(\sqrt{\epsilon+LB_{t,i}}+\sqrt{\epsilon+v'_{t,i}})} \ 
onumber &\le  rac{|m'_{t,i}|}{\sqrt{\epsilon+LB_{t,i}}}  rac{v'_{t,i} - LB_{t,i}}{\epsilon+v'_{t,i}}\ &\hspace*{-2cm} =  rac{\sum_{k=0}^{t}  eta_1^{t-k}|g_{k,i}+\delta_{k,i}|}{\sqrt{\epsilon+\sum_{k=0}^{t} ( eta_2(1-q_V))^{t-k} (g_{k,i}+\delta_{k,i})^2}} \cdot  rac{\sum_{k=0}^{t} ( eta_2^{t-k} - ( eta_2(1-q_V))^{t-k}) (g_{k,i}+\delta_{k,i})^2}{\epsilon+\sum_{k=0}^{t}  eta_2^{t-k} (g_{k,i}+\delta_{k,i})^2} \end{align} The first fraction is bounded by Lemma~ef{app:lemma:cauchy}: $ rac{\sum_{k=0}^{t} eta_1^k |a_{t-k,i}|}{\sqrt{\epsilon+\sum_{k=0}^{t}( eta_2(1-q_V))^k a_{t-k,i}}} \le  rac{1}{\sqrt{1- eta_1^2/( eta_2(1-q_V))}}$. The second fraction is a ratio of weighted sums $ rac{\sum_{k=0}^{t} ( eta_2^k - ( eta_2(1-q_V))^k) a_{t-k,i}}{\epsilon+\sum_{k=0}^{t}  eta_2^k a_{t-k,i}}$. This ratio is bounded by the maximum ratio of its coefficients:  egin{equation*} \max_{k \in \{0,\dots,t\}}  rac{ eta_2^k - ( eta_2(1-q_V))^k}{ eta_2^k} = \max_{k \in \{0,\dots,t\}} (1 - (1-q_V)^k) = 1-(1-q_V)^{t}. \end{equation*} Combining these bounds, the term for Case I is bounded by $ rac{1}{\sqrt{1- eta_1^2/( eta_2(1-q_V))}}(1-(1-q_V)^t)$. 	extbf{Case II (Deviation from Upper Bound):} Similarly, we bound the second term:  egin{align*} |m'_{t,i}| \left(  rac{1}{\sqrt{\epsilon+v'_{t,i}}} -  rac{1}{\sqrt{\epsilon+UB_{t,i}}} ight) &\le  rac{|m'_{t,i}|}{\sqrt{\epsilon+v'_{t,i}}}  rac{UB_{t,i} - v'_{t,i}}{\epsilon+UB_{t,i}} \end{align*} Applying Lemma~ef{app:lemma:cauchy} and the maximum ratio:  egin{equation*} \le  rac{1}{\sqrt{1 -  eta_1^2/ eta_2}} \cdot \left( 1 - (1+q_V)^{-t} ight) \end{equation*} Comparing the bounds from the two cases, the bound from Case I is larger since $1-(1-q_V)^t > 1-(1+q_V)^{-t}$ and the denominator term $\sqrt{1 -  eta_1^2/( eta_2(1-q_V))}$ is smaller than $\sqrt{1 -  eta_1^2/ eta_2}$. Therefore, taking the maximum and summing over $d$ dimensions:  egin{align} |A_2| \le \sum_{i\in[d]} R  rac{1-(1-q_V)^t}{\sqrt{1- rac{ eta_1^2}{ eta_2(1-q_V)}}} =  rac{dR(1-(1-q_V)^t)}{\sqrt{1- rac{ eta_1^2}{ eta_2(1-q_V)}}} \end{align} Combining the bounds for $|A_1|$ and $|A_2|$, we can get the bound for term A:  egin{equation} |A| \le |A_1| + |A_2| \le q_M \cdot dR \cdot C_q +  rac{dR(1-(1-q_V)^t)}{\sqrt{1- rac{ eta_1^2}{ eta_2(1-q_V)}}} 	riangleq Q(t) \end{equation} Now we move on to bound Term B. Let us now focus on bounding Term B from \eqref{eq:fenli}. By expanding the definition of the first moment estimate $m'_{t, i}$, we can decompose Term B into two parts, which we will call Term C and Term D:  egin{align} \sum_{i \in [d]}\mathcal{G}_{t, i} rac{m'_{t, i}}{\sqrt{\epsilon+v'_{t, i}}} &= \sum_{i \in [d]} \mathcal{G}_{t, i} \sum_{k=0}^{t-1}  eta_1^k  rac{g_{t-k, i}+\delta_{t-k,i}}{\sqrt{\epsilon+v'_{t, i}}} \ &= \underbrace{\sum_{i \in [d]} \sum_{k=0}^{t-1} eta_1^k \mathcal{G}_{t-k, i}  rac{g_{t - k, i}+\delta_{t-k,i}}{\sqrt{\epsilon+{v'_{t, i}}}}}_C + \underbrace{\sum_{i \in [d]} \sum_{k=0}^{t-1}  eta_1^k \left(\mathcal{G}_{t, i} - \mathcal{G}_{t -k, i}ight)  rac{g_{t - k, i}+\delta_{t-k,i}}{\sqrt{\epsilon+v'_{t, i}}}}_D. \end{align} The magnitude of Term D, which captures the error from gradient drift, is bounded by Lemma ef{lemma:bound_on_D}:  egin{align} |D| \leq  rac{\eta_t^2 L^2 \sqrt{1 -  eta_1}}{4 (1+q_G)R}\left( \sum_{l=1}^{t-1}
orm{\ub_{t-l}}_2^2\sum_{k=l}^{t - 1} eta_1^k \sqrt{k} ight) + rac{(1+q_G)R}{\sqrt{1 -  eta_1}} \sum_{k=0}^{t-1} \left( rac{ eta_1}{ eta_2}ight)^k \sqrt{k+1}
orm{\Ub_{t-k}}_2^2. \end{align} For Term C, we establish a lower bound on its expectation in Lemma ef{lemma:bound_on_C}:  egin{align} 
onumber \esp{C} &\geq  rac{1}{2}\left(\sum_{i\in [d]} \sum_{k=0}^{t-1} eta_1^k\esp{ rac{\mathcal{G}_{t - k, i}^2}{\sqrt{\epsilon+	ilde{v}_{t, k+1, i}}}}ight) -  rac{2 (1+q_G)R}{\sqrt{1 -  eta_1}}\left(\sum_{i\in [d]} \sum_{k=0}^{t-1} \left( rac{ eta_1}{ eta_2}ight)^k \sqrt{k+1} \esp{
orm{\Ub_{t -k}}_2^2}ight)\ &\quad-d\sum_{k=0}^{t-1} eta_1^kM_{t-k} . \end{align} where $M_{t-k} =  rac{q_GR^2+Lq_WR
orm{\wb_{t-k-1}}_2}{\sqrt{\epsilon}}$. Injecting \eqref{app:eq:descent_proof:almost_there_main} ,\eqref{eq:d_bound_final_rearranged_main}and \eqref{eq:B_term_decomposition_main} into \eqref{eq:fenli} . We get the final lower bound for $\mathcal{G}_t^T \ub_t$:  egin{equation}  egin{aligned} &\esp{\sum_{i\in[d]}\mathcal{G}_{t, i} rac{m_{t, i}}{\sqrt{\epsilon+v_{t, i}}}} \geq  rac{1}{2}\left(\sum_{i\in[d]} \sum_{k=0}^{t - 1}  eta_1^k \esp{  rac{\mathcal{G}_{t - k, i}^2}{\sqrt{\epsilon + 	ilde{v}_{t, k + 1, i}}}}ight)-Q(t)-d\sum_{k=0}^{t-1} eta_1^kM_{t-k} \ &\qquad -  rac{\eta_t^2 L^2}{4 (1+q_G)R}\sqrt{1 -  eta_1}\left( \sum_{l=1}^{t-1}
orm{\ub_{t-l}}_2^2\sum_{k=l}^{t - 1} eta_1^k \sqrt{k} ight) -  rac{3 (1+q_G)R}{\sqrt{1 -  eta_1}} \left(\sum_{k=0}^{t-1} \left( rac{ eta_1}{ eta_2}ight)^k \sqrt{k+1}
orm{\Ub_{t-k}}_2^2ight). \end{aligned} \end{equation} Now lets look back at:  egin{align*} 
onumber &F(\wb_t) \leq F(\wb_{t-1}) - \eta_t \mathcal{G}_t^T \ub_t +  rac{\eta_t^2 L}{2}
orm{\ub_t}^2_2. \end{align*} inject \eqref{app:eq:descent_lemma_main} into it:  egin{align} 
onumber &\esp{F(\wb_t)} \leq \esp{F(\wb_{t-1})} -  rac{\eta_t}{2} \left(\sum_{i\in[d]} \sum_{k = 0}^{t-1}  eta_1^k \esp{  rac{\mathcal{G}_{t - k, i}^2}{ \sqrt{\epsilon + 	ilde{v}_{t, k + 1, i}}}}ight) +  rac{\eta_t^2 L}{2}\esp{
orm{\ub_t}^2_2}+\eta_tQ(t)+\eta_td\sum_{k=0}^{t-1} eta_1^kM_{t-k} \ &\quad +  rac{\eta_t^3 L^2}{4 (1+q_G)R}\sqrt{1 -  eta_1}\left( \sum_{l=1}^{t-1}
orm{\ub_{t-l}}_2^2\sum_{k=l}^{t - 1} eta_1^k \sqrt{k} ight) +  rac{3\eta_t (1+q_G)R}{\sqrt{1 -  eta_1}} \left(\sum_{k=0}^{t-1} \left( rac{ eta_1}{ eta_2}ight)^k \sqrt{k+1}
orm{\Ub_{t-k}}_2^2ight). \end{align} We have for any $k \in \NN$, $k < t$, and any coordinate $i\in [d]$, $\sqrt{\epsilon+	ilde{v}_{t, k+1, i}} \leq (1+q_G)R \sqrt{\sum_{j=0}^{t-1}  eta_2^j}$. Introducing $\Omega_t = \sqrt{\sum_{j=0}^{t-1}  eta_2^j}$, we have  egin{align} 
onumber &\esp{F(\wb_t)} \leq \esp{F(\wb_{t-1})} -  rac{\eta_t}{2 (1+q_G)R \Omega_t}\sum_{k = 0}^{t-1}  eta_1^k \esp{
orm{\mathcal{G}_{t -k}}_2^2} +  rac{\eta_t^2 L}{2}\esp{
orm{\ub_t}^2_2}+\eta_tQ(t)+\eta_td\esp{\sum_{k=0}^{t - 1} eta_1^kM_{t-k}} \ &\quad +  rac{\eta_t^3 L^2}{4 (1+q_G)R}\sqrt{1 -  eta_1}\left( \sum_{l=1}^{t-1}
orm{\ub_{t-l}}_2^2\sum_{k=l}^{t - 1} eta_1^k \sqrt{k} ight) +  rac{3\eta_t (1+q_G)R}{\sqrt{1 -  eta_1}} \left(\sum_{k=0}^{t-1} \left( rac{ eta_1}{ eta_2}ight)^k \sqrt{k+1}
orm{\Ub_{t-k}}_2^2ight). \end{align} Now summing over all iterations $t \in [T]$ for $T \in \NN^*$, and $\eta_t$ is non-decreasing, as well the fact that $F$ is bounded below by $F_*$, we get  egin{align} 
onumber &\underbrace{ rac{1}{2 (1+q_G)R} \sum_{t=1}^T  rac{\eta_t}{\Omega_t}\sum_{k=0}^{t-1}  eta_1^k \esp{
orm{\mathcal{G}_{t -k}}_2^2}}_{	ilde{A}} \leq F(\wb_0) - F_* + \underbrace{ rac{\eta_T^2 L}{2}\sum_{t=1}^T\esp{
orm{\ub_t}^2_2}}_{	ilde{B}}+\underbrace{\eta_T\sum_{t=1}^TQ(t)}_{E_Q}+ \underbrace{\eta_Td\sum_{t=1}^T\esp{\sum_{k=0}^{t-1} eta_1^kM_{t-k}}}_{M}\ &\quad +\underbrace{  rac{\eta_T^3 L^2}{4 (1+q_G)R}\sqrt{1- eta_1} \sum_{t=1}^T \sum_{l=1}^{t-1} \esp{
orm{\ub_{t-l}}^2_2}\sum_{k=l}^{t-1}  eta_1^k \sqrt{k}}_{	ilde{C}} + \underbrace{ rac{3 \eta_T (1+q_G)R}{\sqrt{1-  eta_1}} \sum_{t=1}^T \sum_{k=0}^{t-1} \left( rac{ eta_1}{ eta_2}ight)^k \sqrt{k+1} \esp{
orm{\Ub_{t-k}}^2_2}}_{	ilde{D}} . \end{align} First lets bound Term $	ilde{A}$. We have $\eta_t = (1 -  eta_1) \Omega_t \eta$. Thus, we can simplify the $	ilde{A}$ term from \eqref{app:eq:common_big_main}, also using the usual change of index $j = t - k$, to get  egin{align} 
onumber 	ilde{A} &=  rac{1}{2 (1+q_G)R} \sum_{t=1}^T  rac{\eta_t}{\Omega_t}\sum_{j=1}^{t}  eta_1^{t -j} \esp{
orm{\mathcal{G}_{j}}_2^2}\ 
onumber &=  rac{\eta(1 -  eta_1)}{2 (1+q_G)R} \sum_{j=1}^T \esp{
orm{\mathcal{G}_{j}}_2^2} \sum_{t=j}^{T}  eta_1^{t - j} \ 
onumber &=  rac{\eta}{2 (1+q_G)R} \sum_{j=1}^T (1 -  eta_1^{T - j + 1}) \esp{
orm{\mathcal{G}_{j}}_2^2}\ 
onumber &=  rac{\eta}{2 (1+q_G)R} \sum_{j=1}^{T} (1 -  eta_1^{T - j +1}) \esp{
orm{
abla F(\wb_{j-1})}_2^2}\ &=  rac{\eta}{2 (1+q_G)R} \sum_{j=0}^{T-1} (1 -  eta_1^{T - j}) \esp{
orm{
abla F(\wb_{j})}_2^2}. \end{align} To establish our convergence guarantee, we analyze the expected gradient norm at a randomly selected iteration $	au$, drawn from the set $\{0, \ldots, T-1\}$. The selection is not uniform but is instead weighted to properly account for the influence of the momentum term over the iterations. The probability of selecting a specific iteration $t$ is defined as:  egin{align}  orall t \in \{0, \ldots, T-1\}, \quad \mathbb{P}(	au = t) \propto 1 -  eta_1^{T-t}. \end{align} We can notice that  egin{align} \sum_{j=0}^{T-1} (1 -  eta_1^{T - j}) = T -  eta_1  rac{1 -  eta_1^{T}}{1 -  eta_1} \geq T -  rac{ eta_1}{1 -  eta_1}. \end{align} Introducing  egin{equation} 	ilde{T} = T -  rac{ eta_1}{1 -  eta_1}, \end{equation} we then have  egin{align} 	ilde{A} \geq  rac{\eta 	ilde{T}}{2 (1+q_G)R}\esp{
orm{
abla F(\wb_{	au})}_2^2}. \end{align} Next looking at $	ilde{B}$, we apply Lemma~ef{app:lemma:u},  egin{align} 	ilde{B} \leq B' \left(\ln\left(1 +  rac{((1+q_G)R)^2}{\epsilon(1- eta_2(1-q_V))}ight) - T\ln( eta_2(1-q_V))ight) \end{align} with  egin{gather} B'=  rac{d\eta_T^2 L}{2(1 -  eta_1(1+q_M))(1 -  rac{ eta_1(1+q_M)}{ eta_2(1-q_V)})}. \end{gather} Then looking at $	ilde{C}$ and introducing the change of index $j=t -l$,  egin{align} 
onumber 	ilde{C} &=  rac{\eta_T^3 L^2}{4 (1+q_G)R}\sqrt{1- eta_1} \sum_{t=1}^T \sum_{j=1}^{t} \esp{
orm{\ub_{j}}^2_2}\sum_{k=t - j}^{t-1}  eta_1^k \sqrt{k} \ 
onumber &=  rac{\eta_T^3 L^2}{4 (1+q_G)R}\sqrt{1- eta_1} \sum_{j=1}^T \esp{
orm{\ub_{j}}^2_2}\sum_{t=j}^{T} \sum_{k=t - j}^{t-1}  eta_1^k \sqrt{k}\ 
onumber &=  rac{\eta_T^3 L^2}{4 (1+q_G)R}\sqrt{1- eta_1} \sum_{j=1}^T \esp{
